package com.spendwise.controller;
import com.spendwise.model.Transaction; import com.spendwise.repo.TransactionRepository; import com.spendwise.service.CurrentUser; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import java.util.stream.Collectors;
@RestController @RequestMapping("/api/transactions") public class TransactionController {
 private final TransactionRepository repo; private final CurrentUser current; public TransactionController(TransactionRepository r,CurrentUser c){repo=r;current=c;}
 public record TxRequest(BigDecimal amount,String type,String category,LocalDate transactionDate,String description,String notes){}
 private Transaction owned(Long id){return repo.findById(id).filter(t->t.getUser().getId().equals(current.get().getId())).orElseThrow(()->new NoSuchElementException("Transaction not found"));}
 @GetMapping public List<Transaction> all(@RequestParam(required=false) String type,@RequestParam(required=false) String category,@RequestParam(required=false) String search){return repo.findAllByUserOrderByIdDesc(current.get()).stream().filter(t->type==null||type.isBlank()||t.getType().equalsIgnoreCase(type)).filter(t->category==null||category.isBlank()||t.getCategory().equalsIgnoreCase(category)).filter(t->search==null||search.isBlank()||(t.getDescription()!=null&&t.getDescription().toLowerCase().contains(search.toLowerCase()))).limit(500).collect(Collectors.toList());}
 @PostMapping public Transaction create(@RequestBody TxRequest r){validate(r);Transaction t=new Transaction();t.setUser(current.get());apply(t,r);return repo.save(t);}
 @PutMapping("/{id}") public Transaction update(@PathVariable Long id,@RequestBody TxRequest r){validate(r);Transaction t=owned(id);apply(t,r);return repo.save(t);}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id){repo.delete(owned(id));return ResponseEntity.noContent().build();}
 private void validate(TxRequest r){if(r.amount()==null||r.amount().compareTo(BigDecimal.ZERO)<=0||r.type()==null||!List.of("INCOME","EXPENSE").contains(r.type().toUpperCase())||r.category()==null||r.category().isBlank()||r.transactionDate()==null)throw new IllegalArgumentException("Enter a positive amount, valid type, category and date");}
 private void apply(Transaction t,TxRequest r){t.setAmount(r.amount());t.setType(r.type().toUpperCase());t.setCategory(r.category());t.setTransactionDate(r.transactionDate());t.setDescription(r.description());t.setNotes(r.notes());}
 @GetMapping(value="/export",produces="text/csv") public ResponseEntity<String> export(){StringBuilder b=new StringBuilder("Date,Type,Category,Description,Amount,Notes\n");for(Transaction t:all(null,null,null)){b.append(t.getTransactionDate()).append(',').append(t.getType()).append(',').append(csv(t.getCategory())).append(',').append(csv(t.getDescription())).append(',').append(t.getAmount()).append(',').append(csv(t.getNotes())).append('\n');}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=spendwise-transactions.csv").body(b.toString());}
 private String csv(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
}
